#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum ClaudeContentTypeProbe {
    ContentBlocksHaveType,
    ContentBlocksLackType,
    ContentBlocksUnreadable {
        gap: Rc<ClaudeCodeStreamLineGap>,
    },
}
impl ClaudeContentTypeProbe {
    pub fn gap(&self) -> Rc<ClaudeCodeStreamLineGap> {
        match self {
            ClaudeContentTypeProbe::ContentBlocksHaveType => panic!("no gap on unit variant"),
            ClaudeContentTypeProbe::ContentBlocksLackType => panic!("no gap on unit variant"),
            ClaudeContentTypeProbe::ContentBlocksUnreadable { gap: __val, .. } => __val.clone(),
        }
    }
}

pub fn claude_content_blocks_have_type(content: Rc<JsonValue>, block_type: String) -> Rc<ClaudeContentTypeProbe> {
    match (*content.clone()).clone() {
    JsonValue::JsonArray { elements: elements, .. } => elements.iter().cloned().fold(Rc::new(ClaudeContentTypeProbe::ContentBlocksLackType), |acc: Rc<ClaudeContentTypeProbe>, e: Rc<JsonValue>| match (*acc).clone() {
    ClaudeContentTypeProbe::ContentBlocksUnreadable { gap: gap, .. } => Rc::new(ClaudeContentTypeProbe::ContentBlocksUnreadable {
    gap: gap.clone(),
}),
    ClaudeContentTypeProbe::ContentBlocksHaveType => match (*claude_string_member(e.clone(), "type".to_string())).clone() {
    ClaudeStringMember::StringMemberRead { value: _, .. } => Rc::new(ClaudeContentTypeProbe::ContentBlocksHaveType),
    ClaudeStringMember::StringMemberAbsent => Rc::new(ClaudeContentTypeProbe::ContentBlocksHaveType),
    ClaudeStringMember::StringMemberNull => Rc::new(ClaudeContentTypeProbe::ContentBlocksUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMissing {
    member: "message.content[].type".to_string(),
}),
}),
    ClaudeStringMember::StringMemberMalformed => Rc::new(ClaudeContentTypeProbe::ContentBlocksUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMalformed {
    member: "message.content[].type".to_string(),
}),
}),
},
    ClaudeContentTypeProbe::ContentBlocksLackType => match (*claude_string_member(e.clone(), "type".to_string())).clone() {
    ClaudeStringMember::StringMemberRead { value: s, .. } => if (s.clone() == block_type.clone()) {
        Rc::new(ClaudeContentTypeProbe::ContentBlocksHaveType)
    } else {
        Rc::new(ClaudeContentTypeProbe::ContentBlocksLackType)
    },
    ClaudeStringMember::StringMemberAbsent => Rc::new(ClaudeContentTypeProbe::ContentBlocksLackType),
    ClaudeStringMember::StringMemberNull => Rc::new(ClaudeContentTypeProbe::ContentBlocksUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMissing {
    member: "message.content[].type".to_string(),
}),
}),
    ClaudeStringMember::StringMemberMalformed => Rc::new(ClaudeContentTypeProbe::ContentBlocksUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMalformed {
    member: "message.content[].type".to_string(),
}),
}),
},
}),
    JsonValue::JsonNull => Rc::new(ClaudeContentTypeProbe::ContentBlocksUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMalformed {
    member: "message.content".to_string(),
}),
}),
    JsonValue::JsonBool { value: _, .. } => Rc::new(ClaudeContentTypeProbe::ContentBlocksUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMalformed {
    member: "message.content".to_string(),
}),
}),
    JsonValue::JsonNumber { lexeme: _, .. } => Rc::new(ClaudeContentTypeProbe::ContentBlocksUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMalformed {
    member: "message.content".to_string(),
}),
}),
    JsonValue::JsonString { value: _, .. } => Rc::new(ClaudeContentTypeProbe::ContentBlocksUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMalformed {
    member: "message.content".to_string(),
}),
}),
    JsonValue::JsonObject { members: _, .. } => Rc::new(ClaudeContentTypeProbe::ContentBlocksUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMalformed {
    member: "message.content".to_string(),
}),
}),
}
}

pub fn claude_message_content_has_type(doc: Rc<JsonValue>, block_type: String) -> Rc<ClaudeContentTypeProbe> {
    match (*crate::extdeps_languages_json_parse::json_object_unique_member(doc, "message".to_string())).clone() {
    JsonMemberLookup::JsonMemberFound { value: msg, .. } => match (*crate::extdeps_languages_json_parse::json_object_unique_member(msg.clone(), "content".to_string())).clone() {
    JsonMemberLookup::JsonMemberFound { value: content, .. } => claude_content_blocks_have_type(content.clone(), block_type),
    JsonMemberLookup::JsonMemberAbsent => Rc::new(ClaudeContentTypeProbe::ContentBlocksLackType),
    JsonMemberLookup::JsonMemberDuplicated { count: _, .. } => Rc::new(ClaudeContentTypeProbe::ContentBlocksUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMalformed {
    member: "message.content".to_string(),
}),
}),
    JsonMemberLookup::JsonMemberNotAnObject => Rc::new(ClaudeContentTypeProbe::ContentBlocksUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMalformed {
    member: "message".to_string(),
}),
}),
},
    JsonMemberLookup::JsonMemberAbsent => Rc::new(ClaudeContentTypeProbe::ContentBlocksLackType),
    JsonMemberLookup::JsonMemberDuplicated { count: _, .. } => Rc::new(ClaudeContentTypeProbe::ContentBlocksUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMalformed {
    member: "message".to_string(),
}),
}),
    JsonMemberLookup::JsonMemberNotAnObject => Rc::new(ClaudeContentTypeProbe::ContentBlocksUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMalformed {
    member: "message".to_string(),
}),
}),
}
}

pub fn claude_code_stream_line(line: String) -> Rc<ClaudeCodeStreamLine> {
    match (*crate::extdeps_languages_json_parse::parse_json_document(line)).clone() {
    JsonDocumentParse::JsonDocumentUnreadable { gap: _, .. } => Rc::new(ClaudeCodeStreamLine::ClaudeCodeLineUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineNotJson),
}),
    JsonDocumentParse::JsonDocumentParsed { value: doc, .. } => match (*claude_string_member(doc.clone(), "type".to_string())).clone() {
    ClaudeStringMember::StringMemberRead { value: t, .. } => if (t.clone() == claude_stream_event_type_rate_limit_event()) {
        match (*crate::extdeps_languages_json_parse::json_object_unique_member(doc.clone(), "rate_limit_info".to_string())).clone() {
    JsonMemberLookup::JsonMemberFound { value: info, .. } => claude_rate_limit_info_line(info.clone()),
    JsonMemberLookup::JsonMemberAbsent => Rc::new(ClaudeCodeStreamLine::ClaudeCodeLineUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMissing {
    member: "rate_limit_info".to_string(),
}),
}),
    JsonMemberLookup::JsonMemberDuplicated { count: _, .. } => Rc::new(ClaudeCodeStreamLine::ClaudeCodeLineUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMalformed {
    member: "rate_limit_info".to_string(),
}),
}),
    JsonMemberLookup::JsonMemberNotAnObject => Rc::new(ClaudeCodeStreamLine::ClaudeCodeLineUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMalformed {
    member: "rate_limit_info".to_string(),
}),
}),
}
    } else {
        if (t.clone() == claude_code_stream_event_type_result()) {
            claude_result_line(doc.clone())
        } else {
            if (t.clone() == claude_code_stream_event_type_system()) {
                Rc::new(ClaudeCodeStreamLine::ClaudeCodeSystemLine)
            } else {
                if (t.clone() == claude_code_stream_event_type_assistant()) {
                    match (*claude_message_content_has_type(doc.clone(), claude_code_content_block_type_tool_use())).clone() {
    ClaudeContentTypeProbe::ContentBlocksHaveType => Rc::new(ClaudeCodeStreamLine::ClaudeCodeAssistantLine {
    has_tool_use: true,
}),
    ClaudeContentTypeProbe::ContentBlocksLackType => Rc::new(ClaudeCodeStreamLine::ClaudeCodeAssistantLine {
    has_tool_use: false,
}),
    ClaudeContentTypeProbe::ContentBlocksUnreadable { gap: gap, .. } => Rc::new(ClaudeCodeStreamLine::ClaudeCodeLineUnreadable {
    gap: gap.clone(),
}),
}
                } else {
                    if (t.clone() == claude_code_stream_event_type_user()) {
                        match (*claude_message_content_has_type(doc.clone(), claude_code_content_block_type_tool_result())).clone() {
    ClaudeContentTypeProbe::ContentBlocksHaveType => Rc::new(ClaudeCodeStreamLine::ClaudeCodeUserLine {
    has_tool_result: true,
}),
    ClaudeContentTypeProbe::ContentBlocksLackType => Rc::new(ClaudeCodeStreamLine::ClaudeCodeUserLine {
    has_tool_result: false,
}),
    ClaudeContentTypeProbe::ContentBlocksUnreadable { gap: gap, .. } => Rc::new(ClaudeCodeStreamLine::ClaudeCodeLineUnreadable {
    gap: gap.clone(),
}),
}
                    } else {
                        Rc::new(ClaudeCodeStreamLine::ClaudeCodeOtherLine {
    event_type: t.clone(),
})
                    }
                }
            }
        }
    },
    ClaudeStringMember::StringMemberNull => Rc::new(ClaudeCodeStreamLine::ClaudeCodeLineUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMissing {
    member: "type".to_string(),
}),
}),
    ClaudeStringMember::StringMemberAbsent => Rc::new(ClaudeCodeStreamLine::ClaudeCodeLineUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMissing {
    member: "type".to_string(),
}),
}),
    ClaudeStringMember::StringMemberMalformed => Rc::new(ClaudeCodeStreamLine::ClaudeCodeLineUnreadable {
    gap: Rc::new(ClaudeCodeStreamLineGap::StreamLineMemberMalformed {
    member: "type".to_string(),
}),
}),
},
}
}
